# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "securerandom"
require "spec_helper"

RSpec.describe TimekeepingRelay::FailureReason do
  it "maps failed answers to fixed contract reasons and never echoes response text" do
    answer = ->(status, body) { TimekeepingRelay::Response.new(status: status, body: body) }

    expect(described_class.for(answer.call(409, { "reason" => "stale_generation" }))).to eq("stale_generation")
    expect(described_class.for(answer.call(401, { "reason" => "unauthorized" }))).to eq("unauthorized")
    expect(described_class.for(answer.call(403, { "reason" => "forbidden" }))).to eq("forbidden")
    expect(described_class.for(answer.call(404, { "reason" => "not_found" }))).to eq("not_found")

    # No token is written to a payload or a log line: a reason the contract does
    # not name is replaced, so a credential echoed by the consumer goes nowhere.
    token = "service-#{SecureRandom.hex(24)}"
    expect(described_class.for(answer.call(401, { "reason" => "Bearer #{token}\nINFO forged line" }))).to eq("unrecognized")
    expect(described_class.for(answer.call(502, "<html>Bad gateway</html>"))).to eq("unrecognized")
    expect(described_class.for(answer.call(500, nil))).to eq("unrecognized")
    expect(described_class.for(answer.call(nil, nil))).to eq("unavailable")
  end
end
